package com.mfrp.plens.model;
import jakarta.persistence.*;import lombok.*;import java.time.*;
@Entity @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class ProjectSubmission { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String podName; @Column(nullable=false) private String title; @Column(length=4000,nullable=false) private String problemStatement; @Column(length=4000,nullable=false) private String objectives; @Column(nullable=false) private String technologyStack; private String documentationLink; private Integer alignmentScore; private Integer overlapScore; @Enumerated(EnumType.STRING) private DecisionStatus decisionStatus; private LocalDateTime createdAt; @PrePersist void prepare(){if(decisionStatus==null)decisionStatus=DecisionStatus.PENDING;if(createdAt==null)createdAt=LocalDateTime.now();} }
